-- V17: hardening de RLS, outbox y pagos pendientes.\n-- El runtime no debe borrar tablas y el outbox necesita un claim transversal\n-- acotado para que los workers no dependan de una conexión sin tenant.\nREVOKE DELETE ON ALL TABLES IN SCHEMA public FROM app_user;\nALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE DELETE ON TABLES FROM app_user;\n\nCREATE OR REPLACE FUNCTION claim_projection_outbox(p_limit integer)\nRETURNS TABLE (\n  id uuid,\n  tenant_id uuid,\n  event_id uuid,\n  aggregate_id uuid,\n  aggregate_version bigint,\n  event_type varchar,\n  payload text,\n  attempts smallint\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, public\nAS $$\nDECLARE\n  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);\nBEGIN\n  -- Si el worker murió al reclamar repetidamente el mismo evento, no se reintenta infinito.\n  UPDATE public.projection_outbox o\n     SET status = 'DEAD_LETTERED', dead_lettered_at = now(),\n         last_error = COALESCE(o.last_error, 'Worker interrupted after retry limit')\n   WHERE o.status IN ('PENDING', 'PROCESSING')\n     AND o.next_retry_at <= now()\n     AND o.attempts >= 8;\n\n  RETURN QUERY\n  WITH picked AS (\n    SELECT o.id\n      FROM public.projection_outbox o\n     WHERE o.status IN ('PENDING', 'PROCESSING')\n       AND o.next_retry_at <= now()\n       AND o.attempts < 8\n     ORDER BY o.next_retry_at, o.created_at\n     LIMIT v_limit\n     FOR UPDATE SKIP LOCKED\n  )\n  UPDATE public.projection_outbox o\n     SET status = 'PROCESSING', attempts = (o.attempts + 1)::smallint,\n         next_retry_at = now() + interval '5 minutes'\n    FROM picked\n   WHERE o.id = picked.id\n  RETURNING o.id, o.tenant_id, o.event_id, o.aggregate_id,\n            o.aggregate_version, o.event_type, o.payload::text, o.attempts;\nEND;\n$$;\n-- El worker es una credencial distinta de la que atiende HTTP.\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'outbox_worker') THEN\n    CREATE ROLE outbox_worker WITH NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;\n  END IF;\nEND $$;\nGRANT USAGE ON SCHEMA public TO outbox_worker;\nGRANT SELECT, UPDATE ON public.projection_outbox TO outbox_worker;\nREVOKE ALL ON FUNCTION claim_projection_outbox(integer) FROM PUBLIC;\nREVOKE ALL ON FUNCTION claim_projection_outbox(integer) FROM app_user;\nGRANT EXECUTE ON FUNCTION claim_projection_outbox(integer) TO outbox_worker;\n\n-- Una solicitud de pago no puede generar pagos repetidos por reintentos del workflow.\nCREATE UNIQUE INDEX IF NOT EXISTS ux_payment_one_per_application\n  ON payment (tenant_id, payment_application_id);